"""Independent triangular radial-shell energy derivatives, no supercell indices."""
import json
from pathlib import Path
import mpmath as m

m.mp.dps = 40
source = Path('_scratch/s11c')


def shells(max_radius):
    # r_Q(q)=6(sum_{d|q}chi_3(d)) for Q(u,v)=u^2+uv+v^2.
    yield 0, 1
    for q in range(1, max_radius**2+1):
        multiplicity = 6*sum((0,1,-1)[d%3] for d in range(1,q+1) if q%d==0)
        if multiplicity:
            yield q, multiplicity


def energy(J, strained, cross, basis):
    depth,alpha,rest = (m.mpf('.6'), 10, m.mpf('.94')) if cross else (1,7,1)
    stretch = J**(m.mpf(1)/3)
    gap = stretch if strained else m.mpf(1)
    terms = []
    for q,count in basis:
        if q == 0 and not cross:
            continue
        r = m.sqrt(q*stretch**2+int(cross)*gap**2)
        z = m.exp(-alpha*(r-rest))
        terms.append(count*depth*z*(z-2))
    return m.fsum(terms)


def pressure(n, strained, cross, basis):
    return -m.diff(lambda J: energy(J,strained,cross,basis),1/n)


def derivs(strained,cross,basis):
    e = lambda eta: energy(m.exp(-eta),strained,cross,basis)
    first,second,third = [m.diff(e,0,k) for k in (1,2,3)]
    return first,first+second,first+2*second+third


def compact(xs):
    return [float(x) for x in xs]


for strained in (False,True):
    kind = 'brane' if strained else 'w'
    bases = {R:list(shells(R)) for R in (6,15)}
    for R,basis in bases.items():
        jets = [derivs(strained,cross,basis) for cross in (False,True)]
        total = list(map(sum,zip(*jets)))
        print(json.dumps(dict(stack=kind,R=R,rest_slope_second_within=compact(jets[0]),
                              rest_slope_second_cross=compact(jets[1]),
                              rest_slope_second=compact(total),curvature=float(total[2]/total[1]))))
    rows = [json.loads(line) for line in (source/'neutral_periodic_n4x3_01/stdout').read_text().splitlines()]
    periodic = next(r for r in rows if r['boundary']=='periodic' and r['stack']==kind)
    densities = [m.mpf(str(r['n'])) for r in periodic['rows']]
    for R,basis in bases.items():
        p = {n:sum(pressure(n,strained,cross,basis) for cross in (False,True)) for n in densities}
        calibration = (m.mpf('1.01')**5-1)/5/(p[m.mpf('1.01')]-p[1])
        residues = []
        for geom in ['4x3','6x6','10x10']:
            path = source/('neutral_periodic_n'+geom+'_01/stdout')
            for line in path.read_text().splitlines():
                r=json.loads(line)
                if r['boundary']=='periodic' and r['stack']==kind:
                    residues.extend(abs(float(p[m.mpf(str(s['n']))])-r['rest_virial']-s['raw_change']) for s in r['rows'])
        transfer = periodic['scale_from_finite_patch']/calibration-1
        residual = {str(n):float(calibration*(p[n]-p[1])/((n**5-1)/5)-1) for n in [densities[0],densities[-1]]}
        print(json.dumps(dict(stack=kind,R=R,scale=float(calibration),old_scale_fractional_excess=float(transfer),
                              independent_heldout_errors=residual,all_archive_max_raw_pressure_difference=max(residues))))
